def dedup(nums):
    seen = set()
    out = []
    for n in nums:
        try:
            if n not in seen:
                out.append(n)
                seen.add(n)
        except TypeError:
            # 对于不可哈希的元素，直接添加到结果中（避免重复）
            if n not in out:
                out.append(n)
    return out
