def parse_csv(line):
    result = []
    i = 0
    in_quotes = False
    current_field = ""

    while i < len(line):
        char = line[i]
        if char == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    # Escape quote inside quotes
                    current_field += '"'
                    i += 1
                else:
                    # End of quoted field
                    in_quotes = False
            else:
                # Start of quoted field
                in_quotes = True
        elif char == ',' and not in_quotes:
            # End of field
            result.append(current_field.strip())
            current_field = ""
        else:
            current_field += char
        i += 1

    # Add the last field
    if current_field:
        result.append(current_field.strip())

    return result
